+
+jest.mock('../../hooks', () => ({ useEventManager: jest.fn() }));
+
+const call = jest.fn<Promise<void>, []>();
+const unsubscribe = jest.fn();
+let notify: (event: Record<string, unknown>) => void;
+
+beforeEach(() => {
+    jest.useFakeTimers();
+    call.mockReset().mockResolvedValue(undefined);
+    unsubscribe.mockReset();
+    jest.mocked(useEventManager).mockReturnValue({
+        call,
+        subscribe: (handler: typeof notify) => {
+            notify = handler;
+            return unsubscribe;
+        },
+    } as unknown as ReturnType<typeof useEventManager>);
+});
+
+afterEach(() => {
+    jest.useRealTimers();
+});
+
+it('calls at most once per interval and stops after five attempts', async () => {
+    const { result } = renderHook(usePollEvents);
+    const polling = result.current('PaymentMethods', EVENT_ACTIONS.CREATE);
+
+    for (let step = 1; step <= maxPollingSteps; step += 1) {
+        await jest.advanceTimersByTimeAsync(interval - 1);
+        expect(call).toHaveBeenCalledTimes(step - 1);
+        await jest.advanceTimersByTimeAsync(1);
+        expect(call).toHaveBeenCalledTimes(step);
+    }
+
+    await polling;
+    expect(unsubscribe).toHaveBeenCalledTimes(1);
+    notify({ PaymentMethods: [{ Action: EVENT_ACTIONS.CREATE }] });
+    await jest.advanceTimersByTimeAsync(interval);
+    expect(call).toHaveBeenCalledTimes(maxPollingSteps);
+});
+
